package com.example.demo.repository; import com.example.demo.model.User; import org.springframework.data.domain.Sort; import org.springframework.data.jpa.repository.*; import org.springframework.stereotype.Repository; import java.util.*; @Repository public interface UserRepository extends JpaRepository<User,Long>{ @Query("SELECT u FROM User u") List<User> findAllUsersCustomSorted(Sort sort); }